trait SimpleLogRefinesAsynchronousSingleton<DT: Dispatch> {
    proof fn exists_equiv_behavior(a: SimpleLogBehavior<DT>) -> (b: AsynchronousSingletonBehavior<
        DT,
    >)
        requires
            a.wf(),
        ensures
            b.wf() && behavior_equiv(a, b),
    ;
}

